from pathlib import Path
import hashlib,json,re,subprocess,time
seen=set();order=[];external=set()
def visit(m):
 if m in seen:return
 seen.add(m);p=Path(m.replace('.', '/')+'.lean')
 if not p.exists():external.add(m);return
 for line in p.read_text().splitlines():
  z=re.match(r'(?:public\s+|private\s+)?import\s+(\S+)',line)
  if z:visit(z[1])
 order.append(m)
for m in ['LonelyRunner.FiniteFamilyEquivalence','LonelyRunner.PivotBoundary']:visit(m)
receipt={'source_hashes':{m:hashlib.sha256(Path(m.replace('.', '/')+'.lean').read_bytes()).hexdigest() for m in order},'external_roots':sorted(external),'commands':[],'status':'running'}
rpath=Path('/tmp/astra-minimal-dependency-restore.json')
def run(cmd):
 start=time.monotonic();r=subprocess.run(cmd,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 receipt['commands'].append({'argv':cmd,'exit_code':r.returncode,'seconds':time.monotonic()-start,'output':r.stdout})
 rpath.write_text(json.dumps(receipt,indent=2)+'\n')
 print(json.dumps({'target':cmd[-1],'exit_code':r.returncode,'seconds':round(time.monotonic()-start,2),'output':r.stdout}),flush=True)
 if r.returncode:raise SystemExit(r.returncode)
lake='/home/joshua/.elan/bin/lake'
run([lake,'exe','cache','get',*sorted(external)])
for m in order:
 p=Path(m.replace('.', '/')+'.lean');out=Path('.lake/build/lib/lean')/p.with_suffix('.olean');out.parent.mkdir(parents=True,exist_ok=True)
 run([lake,'env','lean','-j1','-o',str(out),str(p)])
receipt['status']='passed';rpath.write_text(json.dumps(receipt,indent=2)+'\n');print('All 43 project dependency modules compiled serially.',flush=True)
